function textMatches(row: unknown[], query: string) {
  return row.join(" ").toLowerCase().includes(query.trim().toLowerCase());
}

function statusKey(value: unknown) {
  return String(value).trim().toLowerCase().replace(/\s+/g, "-");
}


function ExplorerShell({ title, description, actions, children }:{title:string;description:string;actions?:ReactNode | undefined;children:ReactNode}) {
  return <AppShell><PageHeader title={title} description={description} actions={actions}/>{children}</AppShell>;
}

export function StandardsPage(){
 const [query,setQuery]=useState("");
 const [status,setStatus]=useState("all");
 const [domain,setDomain]=useState("all");
 const [year,setYear]=useState("all");
 const filtered=useMemo(()=>standards.filter(s=>{
   const q=`${s.number} ${s.title} ${s.domain} ${s.category}`.toLowerCase().includes(query.toLowerCase());
   const st=status==="all" || s.status.toLowerCase()===status;
   const dm=domain==="all" || s.domain===domain;
   const yr=year==="all" || String(s.year)===year;
   return q&&st&&dm&&yr;
 }),[query,status,domain,year]);
 const clear=()=>{setStatus("all");setDomain("all");setYear("all")};
 const domains=[...new Set(standards.map(s=>s.domain))]; const years=[...new Set(standards.map(s=>String(s.year)))].sort().reverse();
 return <ExplorerShell title="Standards Explorer" description="Search verified Indian Standards metadata, scope, status, relationships and compliance context." actions={<Button asChild><Link to="/analyze"><FileSearch/>Analyze Tender</Link></Button>}>
  <Panel className="overflow-hidden"><FilterBar placeholder="Search IS number, title, product or keyword..." onSearch={setQuery} onClear={clear} advancedContent={<div className="grid gap-3 md:grid-cols-2"><label className="text-xs font-medium">Domain<Select value={domain} onValueChange={setDomain}><SelectTrigger className="mt-1.5"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All domains</SelectItem>{domains.map(d=><SelectItem key={d} value={d}>{d}</SelectItem>)}</SelectContent></Select></label><label className="text-xs font-medium">Publication year<Select value={year} onValueChange={setYear}><SelectTrigger className="mt-1.5"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All years</SelectItem>{years.map(y=><SelectItem key={y} value={y}>{y}</SelectItem>)}</SelectContent></Select></label></div>}><Select value={status} onValueChange={setStatus}><SelectTrigger className="w-full sm:w-44"><SelectValue placeholder="Status"/></SelectTrigger><SelectContent><SelectItem value="all">All statuses</SelectItem><SelectItem value="active">Active</SelectItem><SelectItem value="revised">Revised</SelectItem><SelectItem value="superseded">Superseded</SelectItem></SelectContent></Select></FilterBar>
  {filtered.length?<div className="-mx-5 -mb-5"><DataTable columns={["Designation","Title","Domain","Category","Year","Status","Relations","Certification"]} rows={filtered.map(s=>[<Link to={`/standards/${encodeURIComponent(s.standardId)}`} className="font-semibold text-primary hover:underline">{s.number}</Link>,s.title,s.domain,s.category,s.year,<StatusBadge>{s.status}</StatusBadge>,s.relationships,<StatusBadge>{s.certification}</StatusBadge>])}/><Pagination count={filtered.length}/></div>:<EmptyState/>}</Panel>
 </ExplorerShell>
}

export function StandardDetailsPage(){
 const { standardId } = useParams<{standardId:string}>();
 if(!DEMO_MODE) return <ExplorerShell title="Standard Details" description="No verified real standard is loaded for this route."><EmptyState title="No standard data available" description="DEMO mode is disabled. Load the verified real dataset to view standard details."/></ExplorerShell>;
 const requestedId=decodeURIComponent(standardId || "");
 const standard=standards.find(s=>s.standardId===requestedId);
 if(!standard) return <ExplorerShell title="Standard Details" description={`Requested record: ${requestedId || "unknown"}`}><EmptyState title="Standard Not Found" description="No standard with this exact ID exists in the active knowledge base. No fallback record has been substituted."/></ExplorerShell>;
 if(standard.standardId!==requestedId) throw new Error("STANDARD_IDENTITY_MISMATCH");
 const related=relationships.filter(r=>r[0]===standard.number);
 return <ExplorerShell title={standard.number} description={standard.title} actions={<><StatusBadge>{standard.status}</StatusBadge><StatusBadge>{standard.verification}</StatusBadge><Button variant="outline"><BookOpen/>Open Source</Button></>}>
  <div className="grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><Panel title="Standard Profile" description="Record resolved from the current route ID"><div className="grid gap-4 sm:grid-cols-2">{[["Designation",standard.number],["Department",standard.department],["Committee",standard.committee],["Domain",standard.domain],["Category",standard.category],["Reaffirmed",standard.reaffirmed]].map(([k,v])=><div key={k} className="border-b pb-3"><p className="text-[11px] uppercase text-muted-foreground">{k}</p><p className="mt-1 text-sm font-medium">{v}</p></div>)}</div></Panel><Panel title="Record Health" description="Provenance and verification"><div className="space-y-3 text-sm"><div className="flex justify-between"><span>Source trust</span><StatusBadge>{standard.sourceTrust}</StatusBadge></div><div className="flex justify-between"><span>Verification</span><StatusBadge>{standard.verification}</StatusBadge></div><div className="flex justify-between"><span>Last verified</span><strong>{standard.lastVerified}</strong></div><div className="flex justify-between"><span>Data mode</span><strong>DEMO</strong></div><div className="flex justify-between"><span>Record ID</span><code className="text-xs">{standard.standardId}</code></div></div></Panel></div>
  <Panel title="Scope" description="Applicability belongs to this exact standard record" className="mt-5"><p className="text-sm leading-6">{standard.scope}</p><div className="mt-4 grid gap-3 md:grid-cols-3"><div className="rounded-md bg-success-soft p-3"><p className="text-xs font-semibold text-success">Included products</p><p className="mt-1 text-sm">{standard.includedProducts.join(" · ") || "Needs Review"}</p></div><div className="rounded-md bg-muted p-3"><p className="text-xs font-semibold">Applications</p><p className="mt-1 text-sm">{standard.applications.join(" · ") || "Needs Review"}</p></div><div className="rounded-md bg-warning-soft p-3"><p className="text-xs font-semibold text-warning">Exclusions</p><p className="mt-1 text-sm">{standard.exclusions.join(" · ") || "No explicit demo exclusions stored"}</p></div></div></Panel>
  <Panel title="Allied Relationships" description="Relationships linked to this exact designation only" className="mt-5 overflow-hidden">{related.length?<div className="-m-5"><DataTable columns={["Source","Target","Relationship","Applicability","Reason","Verification"]} rows={related.map(r=>[r[0],r[1],<StatusBadge tone="info">{r[2]}</StatusBadge>,r[3],r[4],<StatusBadge>{r[5]}</StatusBadge>])}/></div>:<EmptyState title="No allied relationship records" description="No relationship rows are stored for this exact standard in the active demo registry."/>}</Panel>
 </ExplorerShell>;
}

